using HRIS.Api.Data; using HRIS.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Repositories;
public class FamilyChangeRepository : IFamilyChangeRepository { private readonly AppDbContext _db; public FamilyChangeRepository(AppDbContext db)=>_db=db; public Task<List<FamilyChangeRequest>> GetAllAsync(int? employeeId=null)=>_db.FamilyChangeRequests.Include(x=>x.Employee).Include(x=>x.Relationship).Include(x=>x.Gender).Where(x=>employeeId==null||x.EmployeeId==employeeId).OrderByDescending(x=>x.CreatedAt).ToListAsync(); public Task<FamilyChangeRequest?> GetByIdAsync(int id)=>_db.FamilyChangeRequests.Include(x=>x.Employee).Include(x=>x.Relationship).Include(x=>x.Gender).FirstOrDefaultAsync(x=>x.Id==id); public async Task<FamilyChangeRequest> AddAsync(FamilyChangeRequest x){_db.FamilyChangeRequests.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateAsync(FamilyChangeRequest x)=>await _db.SaveChangesAsync(); public Task<EmployeeFamily?> GetFamilyAsync(int employeeId,int familyId)=>_db.EmployeeFamilies.Include(x=>x.Relationship).Include(x=>x.Gender).FirstOrDefaultAsync(x=>x.Id==familyId&&x.EmployeeId==employeeId); }
